        LifecycleState storage state,
        address genesisBootstrapAuthority,
        bool isSealed,
        address sealedPayloadPointer,
        bytes32 currentInventoryRoot,
        uint256 currentInventoryCount
    ) private view returns (BootstrapStateView memory) {
        if (
